import json,collections,re
r=json.load(open('rows2.json'))
c=collections.Counter()
for x in r:
    if not x.get('rec'): continue
    for line in x['rec'].split(' | '):
        c[line[:2]]+=1
for k,v in c.most_common(60): print(repr(k),v)
