import json,collections
r=json.load(open('rows3.json'))
nc=[x for x in r if not x['case']]
print(collections.Counter((x['cite'] is None, bool(x['rec'] and x['rec'].strip(' |'))) for x in nc))
for x in nc[:3]: print(x)
for x in nc:
    if x['rec'] and x['rec'].strip(' |') : print(x['file'],x['page'],x['cite'],x['rec'][:200])
c=collections.Counter((x['file'],x['case']) for x in r if x['case'])
for k,v in c.items():
    if v>1: print('dup',k,v,[ (x['page'],x['cite'],x['rec'][:80] if x['rec'] else None) for x in r if (x['file'],x['case'])==k])
